// Deterministic 4-second, 4 FPS, 80x48 MPEG-4 Part 2 fixture generated with
// FFmpeg 7.1.5. It is black through 2.25s, then hard-cuts to white so the
// default scene-change detector has one stable, non-interval-aligned scene.
//
// ffmpeg -y \
//   -f lavfi -i color=c=black:s=80x48:r=4:d=2.25 \
//   -f lavfi -i color=c=white:s=80x48:r=4:d=1.75 \
//   -filter_complex "[0:v][1:v]concat=n=2:v=1:a=0[v]" \
//   -map "[v]" -c:v mpeg4 -q:v 5 -movflags +faststart fixture.mp4
const REAL_SCENE_CHANGE_MP4_BASE64 =
  '';

export const REAL_SCENE_CHANGE_MP4 = Buffer.from(
  REAL_SCENE_CHANGE_MP4_BASE64,
  'base64'
);
